mapper.delete:
DELETE FROM trade_matches
WHERE account_id = #{accountId}
  AND security_id = #{securityId}

mapper.select:
SELECT tm.holding_days
FROM trade_matches tm
JOIN trades sell_t ON sell_t.trade_id = tm.sell_trade_id
WHERE tm.account_id IN

    #{accountId}

AND sell_t.traded_at >= #{since}
